alter table public.rollover_execution_handler_registry drop constraint rollover_execution_handler_registry_mutation_class_check;
alter table public.rollover_execution_handler_registry add constraint rollover_execution_handler_registry_mutation_class_check check(mutation_class in('read_only','contract_domain','roster_domain','taxi_domain','taxi_eligibility_domain','ir_domain','draft_inventory_domain','rookie_authority_domain','rookie_eligibility_domain','dead_cap_domain','team_cap_domain'));
insert into public.rollover_execution_handler_registry(operation_code,operation_order,handler_version,input_schema_version,result_schema_version,execution_owner,mutation_class,metadata) values('RECALCULATE_TARGET_TEAM_CAPS',23,1,'phase3b10b-cap-input-v1','phase3b10b-cap-result-v1','execution','team_cap_domain',jsonb_build_object('phase','3B.10B','publication',false,'auto_release',false,'sunday_penalty',false,'v_team_caps',false));
do $$declare d text;sig regprocedure;begin foreach sig in array array['public.guard_contract_write_during_rollover()'::regprocedure,'public.guard_season_roster_assignment_insert_phase3b8a()'::regprocedure,'public.guard_phase3b9a_draft_inventory()'::regprocedure,'public.guard_phase3b9b_rookie_authority()'::regprocedure,'public.guard_phase3b9c_rookie_eligibility()'::regprocedure] loop select pg_get_functiondef(sig) into d;d:=replace(d,'''phase3b10a-v1'')','''phase3b10a-v1'',''phase3b10b-v1'')');execute d;end loop;end$$;
create table public.prepared_team_cap_sets(id uuid primary key default gen_random_uuid(),rollover_execution_id uuid not null unique references public.rollover_executions(id),league_id uuid not null references public.leagues(id),target_season_id uuid not null references public.league_seasons(id),frozen_snapshot_hash text not null,target_assignment_set_hash text not null,contract_evidence_hash text not null,dead_cap_evidence_hash text not null,cap_limit numeric(12,2) not null check(cap_limit>0),cap_limit_fingerprint text not null,canonical_team_count integer not null,aggregate_cap_set_hash text not null,status text not null check(status='prepared_unpublished'),schema_version text not null check(schema_version='phase3b10b-cap-v1'),created_at timestamptz not null default clock_timestamp());
create table public.prepared_team_caps(id uuid primary key default gen_random_uuid(),cap_set_id uuid not null references public.prepared_team_cap_sets(id),league_id uuid not null references public.leagues(id),target_season_id uuid not null references public.league_seasons(id),league_team_id uuid not null references public.league_teams(id),salary_cap_limit numeric(12,2) not null,active_target_salary numeric(12,2) not null,prepared_dead_cap numeric(12,2) not null,total_cap_charge numeric(12,2) not null,cap_space numeric(12,2) not null,is_over_cap boolean not null,over_cap_amount numeric(12,2) not null,publication_blocked boolean not null,blocking_reason_codes text[] not null,active_contract_count integer not null,dead_cap_obligation_count integer not null,contract_evidence_hash text not null,dead_cap_evidence_hash text not null,deterministic_row_fingerprint text not null,published_at timestamptz,created_at timestamptz not null default clock_timestamp(),unique(cap_set_id,league_team_id),check(published_at is null),check(total_cap_charge=active_target_salary+prepared_dead_cap),check(cap_space=salary_cap_limit-total_cap_charge),check(is_over_cap=(total_cap_charge>salary_cap_limit)),check(over_cap_amount=greatest(total_cap_charge-salary_cap_limit,0)),check(publication_blocked=is_over_cap));
alter table public.prepared_team_cap_sets enable row level security;alter table public.prepared_team_caps enable row level security;revoke all on public.prepared_team_cap_sets,public.prepared_team_caps from public,anon,authenticated;grant select,insert on public.prepared_team_cap_sets,public.prepared_team_caps to service_role;
create policy prepared_cap_set_read on public.prepared_team_cap_sets for select to authenticated using(exists(select 1 from public.league_memberships m where m.league_id=prepared_team_cap_sets.league_id and m.user_id=auth.uid() and m.role='commissioner'));create policy prepared_cap_row_read on public.prepared_team_caps for select to authenticated using(exists(select 1 from public.league_memberships m where m.league_id=prepared_team_caps.league_id and m.user_id=auth.uid() and m.role='commissioner'));
create or replace function public.guard_phase3b10b_caps() returns trigger language plpgsql security definer set search_path=pg_catalog,public as $$declare lid uuid:=coalesce(new.league_id,old.league_id);begin if tg_op in('UPDATE','DELETE') then raise exception 'prepared_team_cap_immutable';end if;if public.has_active_rollover_cutover_lock(lid) and coalesce(current_setting('app.rollover_typed_execution',true),'') not in('phase3b7c-v1','phase3b8a-v1','phase3b8b-v1','phase3b8c-v1','phase3b8d-v1','phase3b9a-v1','phase3b9b-v1','phase3b9c-v1','phase3b10a-v1','phase3b10b-v1') then raise exception 'rollover_cutover_cap_writes_blocked';end if;return new;end$$;
create trigger prepared_cap_sets_guard before insert or update or delete on public.prepared_team_cap_sets for each row execute function public.guard_phase3b10b_caps();create trigger prepared_cap_rows_guard before insert or update or delete on public.prepared_team_caps for each row execute function public.guard_phase3b10b_caps();
create or replace function public.guard_phase3b10b_salary_cap_setting() returns trigger language plpgsql security definer set search_path=pg_catalog,public as $$begin if new.salary_cap is distinct from old.salary_cap and public.has_active_rollover_cutover_lock(new.league_id) and coalesce(current_setting('app.rollover_typed_execution',true),'')<>'phase3b10b-v1' then raise exception 'rollover_cutover_salary_cap_changes_blocked';end if;return new;end$$;
create trigger league_rules_salary_cap_cutover_guard before update on public.league_rules for each row execute function public.guard_phase3b10b_salary_cap_setting();
create or replace function public.write_prepared_caps_phase3b10b_private(p_rollover_execution_id uuid,p_execution_plan_id uuid,p_approval_id uuid,p_actor uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$declare x public.rollover_executions%rowtype;s public.rollover_execution_input_snapshots%rowtype;aset public.rollover_target_roster_assignment_sets%rowtype;rules jsonb;cap numeric;t public.league_teams%rowtype;active numeric;dead numeric;ac int;dc int;rf text;material jsonb:='[]';sethash text;cs public.prepared_team_cap_sets%rowtype;over_count int:=0;written int:=0;begin select * into x from public.rollover_executions where id=p_rollover_execution_id;if not exists(select 1 from public.rollover_execution_locks l where l.rollover_execution_id=x.id and l.approval_id=p_approval_id and l.status='active' for update) then perform public.raise_phase3b6c1_failure('cap_cutover_lock_missing','{}');end if;select * into s from public.rollover_execution_input_snapshots where rollover_execution_id=x.id for share;select canonical_payload into rules from public.rollover_execution_input_snapshot_components where snapshot_id=s.id and component_name='league_rules';cap:=coalesce((rules->>'salary_cap')::numeric,(rules->>'current_salary_cap')::numeric);if cap is null or cap<=0 then perform public.raise_phase3b6c1_failure('cap_limit_missing','{}');end if;select * into aset from public.rollover_target_roster_assignment_sets where rollover_execution_id=x.id for share;if aset.id is null then perform public.raise_phase3b6c1_failure('cap_assignment_set_mismatch','{}');end if;perform 1 from public.league_teams where league_id=x.league_id order by id for share;perform 1 from public.season_roster_assignments where assignment_set_id=aset.id order by league_team_id,sleeper_player_id for share;perform 1 from public.rollover_dead_cap_obligations where rollover_execution_id=x.id order by league_team_id,contract_agreement_id for share;
 for t in select * from public.league_teams where league_id=x.league_id order by id loop select coalesce(sum(c.salary),0),count(*) into active,ac from public.season_roster_assignments r join public.contract_seasons c on c.id=r.target_contract_season_id where r.assignment_set_id=aset.id and r.league_team_id=t.id and c.obligation_status='active';select coalesce(sum(o.amount),0),count(*) into dead,dc from public.rollover_dead_cap_obligations o where o.rollover_execution_id=x.id and o.league_team_id=t.id;rf:=public.rollover_material_fingerprint(jsonb_build_object('team',t.id,'cap',cap,'active',active,'dead',dead,'contracts',ac,'obligations',dc,'assignment_hash',aset.aggregate_assignment_set_hash));material:=material||jsonb_build_array(jsonb_build_object('team',t.id,'hash',rf));if active+dead>cap then over_count:=over_count+1;end if;end loop;sethash:=public.rollover_material_fingerprint(material);insert into public.prepared_team_cap_sets(rollover_execution_id,league_id,target_season_id,frozen_snapshot_hash,target_assignment_set_hash,contract_evidence_hash,dead_cap_evidence_hash,cap_limit,cap_limit_fingerprint,canonical_team_count,aggregate_cap_set_hash,status,schema_version) values(x.id,x.league_id,aset.target_league_season_id,s.aggregate_snapshot_fingerprint,aset.aggregate_assignment_set_hash,public.rollover_material_fingerprint(jsonb_build_object('assignment',aset.aggregate_assignment_set_hash)),public.rollover_material_fingerprint((select jsonb_agg(deterministic_fingerprint order by contract_agreement_id) from public.rollover_dead_cap_obligations where rollover_execution_id=x.id)),cap,public.rollover_material_fingerprint(rules),(select count(*) from public.league_teams where league_id=x.league_id),sethash,'prepared_unpublished','phase3b10b-cap-v1') returning * into cs;
 for t in select * from public.league_teams where league_id=x.league_id order by id loop select coalesce(sum(c.salary),0),count(*) into active,ac from public.season_roster_assignments r join public.contract_seasons c on c.id=r.target_contract_season_id where r.assignment_set_id=aset.id and r.league_team_id=t.id and c.obligation_status='active';select coalesce(sum(o.amount),0),count(*) into dead,dc from public.rollover_dead_cap_obligations o where o.rollover_execution_id=x.id and o.league_team_id=t.id;rf:=public.rollover_material_fingerprint(jsonb_build_object('team',t.id,'cap',cap,'active',active,'dead',dead,'contracts',ac,'obligations',dc,'assignment_hash',aset.aggregate_assignment_set_hash));insert into public.prepared_team_caps(cap_set_id,league_id,target_season_id,league_team_id,salary_cap_limit,active_target_salary,prepared_dead_cap,total_cap_charge,cap_space,is_over_cap,over_cap_amount,publication_blocked,blocking_reason_codes,active_contract_count,dead_cap_obligation_count,contract_evidence_hash,dead_cap_evidence_hash,deterministic_row_fingerprint) values(cs.id,x.league_id,aset.target_league_season_id,t.id,cap,active,dead,active+dead,cap-active-dead,active+dead>cap,greatest(active+dead-cap,0),active+dead>cap,case when active+dead>cap then array['hard_cap_exceeded'] else '{}' end,ac,dc,cs.contract_evidence_hash,cs.dead_cap_evidence_hash,rf);written:=written+1;end loop;return jsonb_build_object('team_count',written,'over_cap_team_count',over_count,'publication_blocked_team_count',over_count,'cap_limit',cap,'aggregate_cap_set_hash',sethash,'mutation_count',written+1,'postcondition_count',8);end$$;
create or replace function public.execute_rollover_typed_handler_phase3b10b_private(p_operation jsonb,p_rollover_execution_id uuid,p_execution_plan_id uuid,p_approval_id uuid,p_actor uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$declare code text:=p_operation->>'operation_type';result jsonb;begin if code<>'RECALCULATE_TARGET_TEAM_CAPS' then return public.execute_rollover_typed_handler_phase3b10a_private(p_operation,p_rollover_execution_id,p_execution_plan_id,p_approval_id,p_actor);end if;if(p_operation->>'operation_index')::int<>23 then perform public.raise_phase3b6c1_failure('unsupported_handler_version','{}');end if;result:=public.write_prepared_caps_phase3b10b_private(p_rollover_execution_id,p_execution_plan_id,p_approval_id,p_actor);return jsonb_build_object('operation_code',code,'handler_version',1,'result',result||jsonb_build_object('operation_mutation_count',(result->>'mutation_count')::int));end$$;
do $$declare d text;begin select pg_get_functiondef('public.execute_rollover_plan_phase3b10a_private(jsonb,uuid)'::regprocedure) into d;d:=replace(d,'execute_rollover_plan_phase3b10a_private','execute_rollover_plan_phase3b10b_private');d:=replace(d,'execute_rollover_typed_handler_phase3b10a_private','execute_rollover_typed_handler_phase3b10b_private');d:=replace(d,'''APPLY_DEAD_CAP_OBLIGATIONS'')','''APPLY_DEAD_CAP_OBLIGATIONS'',''RECALCULATE_TARGET_TEAM_CAPS'')');d:=replace(d,'Phase 3B.10A','Phase 3B.10B');d:=replace(d,'phase3b10a-v1','phase3b10b-v1');execute d;end$$;
create or replace function public.execute_rollover_plan_authenticated(p_request jsonb) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$declare actor uuid:=public.require_authenticated_user();x public.rollover_executions%rowtype;begin if p_request?'actor_user_id' or p_request?'executed_by' then raise exception 'actor spoofing forbidden';end if;select * into x from public.rollover_executions where id=(p_request->>'rollover_execution_id')::uuid;if x.id is null then raise exception 'execution not found';end if;perform public.require_commissioner_authority(x.league_id);return public.execute_rollover_plan_phase3b10b_private(p_request,actor);end$$;
revoke all on function public.write_prepared_caps_phase3b10b_private(uuid,uuid,uuid,uuid),public.execute_rollover_typed_handler_phase3b10b_private(jsonb,uuid,uuid,uuid,uuid),public.execute_rollover_plan_phase3b10b_private(jsonb,uuid),public.guard_phase3b10b_caps() from public,anon,authenticated,service_role;revoke all on function public.execute_rollover_plan_authenticated(jsonb) from public,anon,authenticated,service_role;grant execute on function public.execute_rollover_plan_authenticated(jsonb) to authenticated;commit;
